# Compares reference values regenerated by dev/ref/all.R with the stored
# ones, leaf by leaf, at the tolerance the test that uses each applies
# (tests/testthat/ref/tol.csv, which a test keeps complete). From the
# package root:
#   Rscript dev/ref/cmp.R OLD NEW
# OLD holds the stored fixtures and tol.csv (tests/testthat/ref), NEW the
# regenerated ones and all.R's status.csv. Writes NEW/diff.csv (one row
# per leaf) and NEW/summary.md (per fixture, and per reference function:
# the first two segments of a path), prints the summary, and exits 1 when
# a value is outside its tolerance or a fixture is missing without its
# generator having been skipped for want of a package.
a <- commandArgs(TRUE)
if (length(a) != 2L) stop("usage: Rscript dev/ref/cmp.R OLD NEW")
h <- new.env()
sys.source(file.path("tests", "testthat", "helper.R"), envir = h)
tab <- utils::read.csv(file.path(a[1], "tol.csv"), stringsAsFactors = FALSE)
sf <- file.path(a[2], "status.csv")
st <- if (file.exists(sf)) utils::read.csv(sf, stringsAsFactors = FALSE)

# one leaf: o stored, n regenerated
one <- function(o, n, kind, tol) {
  r <- list(abs = 0, rel = 0, same = identical(o, n), ok = TRUE, note = "")
  if (r$same) return(r)
  r[c("abs", "rel")] <- NA_real_
  at <- function(x) attributes(x)[c("names", "dimnames", "levels")]
  if (!is.numeric(o) || !is.numeric(n) || length(o) != length(n) ||
        !identical(at(o), at(n)) || !identical(is.na(o), is.na(n))) {
    r$ok <- kind == "report"
    r$note <- "differs in type, length, names or missing values"
    return(r)
  }
  o <- as.vector(o)
  n <- as.vector(n)
  k <- is.finite(o) & is.finite(n)
  if (!identical(o[!k], n[!k])) {
    r$ok <- kind == "report"
    r$note <- "infinite values differ"
    return(r)
  }
  d <- abs(n[k] - o[k])
  r$abs <- max(c(0, d))
  r$rel <- max(c(0, d / pmax(abs(o[k]), 1e-300)))
  eq <- function(x, y) isTRUE(all.equal(x, y, tolerance = tol))
  r$ok <- switch(kind,
    report = TRUE,
    exact = FALSE,
    equal = eq(o, n),
    each = all(mapply(eq, o, n)),
    maxrel = r$rel <= tol,
    maxabs = r$abs <= tol,
    stop("unknown kind ", kind)
  )
  r
}

rows <- list()
fix <- data.frame()
for (f in unique(tab$fixture)) {
  of <- file.path(a[1], paste0(f, ".txt"))
  nf <- file.path(a[2], paste0(f, ".txt"))
  s <- if (!is.null(st)) st[st$name == f, ]
  if (!file.exists(nf)) {
    skip <- !is.null(s) && nrow(s) && s$status[1] == "skipped"
    fix <- rbind(fix, data.frame(
      fixture = f, status = if (skip) "skipped" else "missing",
      leaves = NA, same = NA, over = NA, abs = NA, rel = NA,
      detail = if (!is.null(s) && nrow(s)) s$detail[1] else "no fixture"
    ))
    next
  }
  ol <- dget(of)
  nl <- dget(nf)
  pk <- paste(names(nl$pkgs), nl$pkgs, collapse = ", ")
  ol$pkgs <- nl$pkgs <- NULL
  ol <- h$refleaf(ol)
  nl <- h$refleaf(nl)
  t <- tab[tab$fixture == f, ]
  i <- h$refrow(t$path, names(ol))
  for (j in seq_along(ol)) {
    p <- names(ol)[j]
    kind <- if (is.na(i[j])) "exact" else t$kind[i[j]]
    tol <- if (is.na(i[j])) 0 else t$tol[i[j]]
    r <- if (p %in% names(nl)) {
      one(ol[[j]], nl[[p]], kind, tol)
    } else {
      list(abs = NA, rel = NA, same = FALSE, ok = FALSE, note = "missing")
    }
    if (is.na(i[j])) r$note <- paste(r$note, "no row in tol.csv")
    rows[[length(rows) + 1L]] <- data.frame(
      fixture = f, path = p,
      fn = paste(utils::head(strsplit(p, "/", fixed = TRUE)[[1]], 2),
                 collapse = "/"),
      n = length(ol[[j]]), kind = kind, tol = tol, same = r$same,
      abs = r$abs, rel = r$rel, ok = r$ok, note = trimws(r$note)
    )
  }
  extra <- setdiff(names(nl), names(ol))
  d <- do.call(rbind, rows[vapply(rows, function(x) x$fixture == f, NA)])
  bad <- sum(!d$ok) + length(extra)
  mx <- function(x) if (all(is.na(x))) NA else max(x, na.rm = TRUE)
  fix <- rbind(fix, data.frame(
    fixture = f, status = if (bad) "over" else "ok", leaves = nrow(d),
    same = sum(d$same), over = bad, abs = mx(d$abs), rel = mx(d$rel),
    detail = paste0(pk, if (length(extra)) {
      paste("; new leaves:", paste(extra, collapse = " "))
    })
  ))
}
diff <- do.call(rbind, rows)
utils::write.csv(diff, file.path(a[2], "diff.csv"), row.names = FALSE)

g <- do.call(rbind, lapply(split(diff, list(diff$fixture, diff$fn),
                                 drop = TRUE), function(d) {
  data.frame(fixture = d$fixture[1], fn = d$fn[1], leaves = nrow(d),
             same = sum(d$same), tol = paste(unique(paste(d$kind, d$tol)),
                                             collapse = "; "),
             abs = max(c(0, d$abs), na.rm = TRUE),
             rel = max(c(0, d$rel), na.rm = TRUE), ok = all(d$ok))
}))
g <- g[order(g$fixture, g$fn), ]
fmt <- function(x) ifelse(is.na(x), "", formatC(x, digits = 3, format = "g"))
md <- c(
  sprintf("## Reference values on %s, %s", R.version.string,
          R.version$platform), "",
  "| fixture | status | leaves | identical | over tolerance | max abs | max rel | detail |",
  "|---|---|---|---|---|---|---|---|",
  sprintf("| %s | %s | %s | %s | %s | %s | %s | %s |", fix$fixture,
          fix$status, fix$leaves, fix$same, fix$over, fmt(fix$abs),
          fmt(fix$rel), fix$detail),
  "", "### Reference functions whose values are not bit-identical", "",
  "| fixture | function | leaves | identical | tolerance | max abs | max rel | within |",
  "|---|---|---|---|---|---|---|---|"
)
nd <- g[g$same < g$leaves, ]
md <- c(md, if (nrow(nd)) {
  sprintf("| %s | %s | %d | %d | %s | %s | %s | %s |", nd$fixture, nd$fn,
          nd$leaves, nd$same, nd$tol, fmt(nd$abs), fmt(nd$rel),
          ifelse(nd$ok, "yes", "**NO**"))
} else {
  "| (none) | | | | | | | |"
})
writeLines(md, file.path(a[2], "summary.md"))
writeLines(md)
quit(status = as.integer(any(fix$status %in% c("over", "missing"))))
